def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    divider = next((c for c in range(w)
                    if all(grid[r][c] == 2 for r in range(h))), None)
    if divider is None:
        return out
    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out
    lo, hi = min(c for r, c in cells), max(c for r, c in cells)
    # Add the 8 line immediately beside the object on the divider side.
    target = hi + 1 if hi < divider else lo - 1
    if 0 <= target < w:
        for r in range(h):
            out[r][target] = 8
    return out
